<section class="section-heading"><div><h2>Your grid’s identity</h2><p>Custom branding is user data. Grid configuration and built-in artwork stay separate.</p></div></section><div class="editor-layout"><form method="post" enctype="multipart/form-data" class="studio-panel" id="branding-form"><?php $hidden('branding_save')?><?php foreach(array('title'=>'Site title (blank uses grid name)','heading'=>'Welcome heading','welcome'=>'Welcome text','footer'=>'Footer text') as $key=>$label):?><label><?=ag_h($label)?><?php if(in_array($key,array('welcome','footer'),true)):?><textarea name="branding[<?=$key?>]" maxlength="<?=$key==='welcome'?2000:500?>"><?=ag_h($state['branding'][$key])?></textarea><?php else:?><input name="branding[<?=$key?>]" value="<?=ag_h($state['branding'][$key])?>" maxlength="<?=$key==='title'?120:240?>"><?php endif ?></label><?php endforeach ?><label>Primary accent (blank follows theme)<input name="branding[accent]" value="<?=ag_h($state['branding']['accent'])?>" placeholder="#e2b64f" pattern="#[a-fA-F0-9]{6}"></label><label>Button style<select name="branding[button]"><?php foreach(array(''=>'Follow theme','rounded'=>'Rounded','square'=>'Square','pill'=>'Pill') as $key=>$label):?><option value="<?=$key?>" <?=$state['branding']['button']===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><div class="branding-assets"><?php foreach(array('logo'=>'Logo','mark'=>'Secondary mark','background'=>'Background','favicon'=>'Favicon') as $key=>$label):?><article class="brand-image-card"><div class="brand-image-preview" data-brand-image="<?=$key?>"><?php if($state['branding'][$key]&&ag_sd_asset_path($state['branding'][$key])):?><img src="<?=ag_h(ag_sd_asset_url($state['branding'][$key]))?>" alt="<?=ag_h($label)?>"><?php else:?><span class="asset-placeholder">◇<small>Default <?=ag_h(strtolower($label))?></small></span><?php endif ?></div><h3><?=ag_h($label)?></h3><input type="hidden" name="branding[<?=$key?>]" value="<?=ag_h($state['branding'][$key])?>"><label>Choose image<input type="file" name="<?=$key?>" accept="<?=$key==='favicon'?'image/png':'image/png,image/jpeg,image/gif,image/webp'?>"></label><p class="small-note"><?=$key==='favicon'?'PNG, at most 512 × 512':'PNG, JPG, GIF or WebP, up to 8 MB'?></p><?php if($state['branding'][$key]):?><label class="check"><input type="checkbox" name="removeBranding[<?=$key?>]" value="1"> Use default</label><?php endif ?></article><?php endforeach ?></div><button>Apply branding</button><p>Welcome/footer bindings follow this content in starter designs and bound Page Designer blocks. Saving this form explicitly applies shared branding.</p></form><section><h2>Branding preview</h2><div class="preview-stage"><iframe id="branding-frame" title="Live branding preview" src="/Other/site-theme-preview.php?scope=public"></iframe></div><p>Uploads preview locally. No branding becomes active until Apply branding.</p></section></div>
